"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

/*
 * Playdesk MegaMenu — a wide floating window split into columns, each row a
 * desk list item with an optional glyph well.
 */

export interface MegaMenuItem {
  title: string;
  description?: string;
  href?: string;
  icon?: React.ReactNode;
}

export interface MegaMenuSection {
  heading: string;
  items: MegaMenuItem[];
}

export interface MegaMenuProps {
  trigger: React.ReactNode;
  sections: MegaMenuSection[];
  className?: string;
}

/**
 * True when the trigger renders a native button: a `<button>`, or a component
 * such as Button that renders one (a component type is a function or an
 * object, a host element type is a string). Any other element needs Base UI's
 * non-native handling, so it stays focusable and opens on Enter and Space.
 */
function rendersNativeButton(trigger: React.ReactElement) {
  return trigger.type === "button" || trigger.type instanceof Object;
}

export function MegaMenu({ trigger, sections, className }: MegaMenuProps) {
  return (
    <Popover>
      <PopoverTrigger
        render={React.isValidElement(trigger) ? trigger : undefined}
        nativeButton={!React.isValidElement(trigger) || rendersNativeButton(trigger)}
      >
        {React.isValidElement(trigger) ? undefined : trigger}
      </PopoverTrigger>
      <PopoverContent align="start" className={cn("w-[40rem] p-4", className)}>
        <div className="grid grid-cols-2 gap-2">
          {sections.map((section) => (
            <div key={section.heading} className="space-y-1">
              <h4 className="px-2.5 pb-1 text-[0.6875rem] font-bold tracking-[0.08em] text-muted-foreground">
                {section.heading}
              </h4>
              {section.items.map((item) => (
                <a
                  key={item.title}
                  href={item.href ?? "#"}
                  className="flex gap-2.5 rounded-md px-2.5 py-2 transition-colors duration-fast hover:bg-accent"
                >
                  {item.icon ? (
                    <span className="mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-full bg-muted text-muted-foreground [&_svg]:size-3.5">
                      {item.icon}
                    </span>
                  ) : null}
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-foreground">
                      {item.title}
                    </span>
                    {item.description ? (
                      <span className="block text-xs leading-relaxed text-muted-foreground">
                        {item.description}
                      </span>
                    ) : null}
                  </span>
                </a>
              ))}
            </div>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}
